# This file is the backend database manager for the application. It is responsible for managing the database connection and providing an interface for the application to interact with the database.
# Do not edit this file unless you are sure of what you are doing. Any changes made to this file should be reported.
# The initial prototype uses SQLite as the database. However, the code is designed to be easily adaptable to other databases in the future.
# Gateway to 2 tables: users, schedule
#
# NOTE: renamed from dbm.py because that name shadows Python's standard-library `dbm` package.

import os
import sqlite3

DB_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'database.db')

# Timetable shape: Monday-Friday, 6 periods per day.
DAYS_PER_WEEK = 5
PERIODS_PER_DAY = 6
VALID_ROLES = ('user', 'head', 'admin')


def get_db_connection():
    """Establishes a connection to the SQLite database with foreign keys enabled."""
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.row_factory = sqlite3.Row
        conn.execute('PRAGMA foreign_keys = ON;')
        return conn
    except sqlite3.Error as e:
        print(f"Database connection error: {e}")
        return None


def close_db_connection(conn):
    """Closes the database connection."""
    if conn:
        conn.close()


def initialize_database():
    """Initializes the database by creating necessary tables if they don't exist."""
    conn = get_db_connection()
    if conn is not None:
        try:
            with conn:
                conn.execute(f'''
                    CREATE TABLE IF NOT EXISTS users (
                        id INTEGER PRIMARY KEY,
                        username TEXT NOT NULL UNIQUE COLLATE NOCASE,
                        email TEXT NOT NULL UNIQUE COLLATE NOCASE,
                        password_hash BLOB NOT NULL,
                        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                        role TEXT NOT NULL DEFAULT 'user'
                            CHECK (role IN ({", ".join(repr(r) for r in VALID_ROLES)}))
                    ) STRICT;
                ''')
                conn.execute(f'''
                    CREATE TABLE IF NOT EXISTS schedule (
                        id INTEGER PRIMARY KEY,
                        user_id INTEGER NOT NULL,
                        day_of_week INTEGER NOT NULL CHECK (day_of_week BETWEEN 1 AND {DAYS_PER_WEEK}),
                        period_number INTEGER NOT NULL CHECK (period_number BETWEEN 1 AND {PERIODS_PER_DAY}),
                        subject TEXT,
                        UNIQUE (user_id, day_of_week, period_number),
                        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
                    ) STRICT;
                ''')
        except sqlite3.Error as e:
            print(f"Database initialization error: {e}")
        finally:
            close_db_connection(conn)


def execute_query(query, params=()):
    """Executes a SQL query with optional parameters and returns fetched rows (None on error)."""
    conn = get_db_connection()
    if conn is not None:
        try:
            with conn:
                cursor = conn.execute(query, params)
                return cursor.fetchall()
        except sqlite3.Error as e:
            print(f"Database query error: {e}")
            return None
        finally:
            close_db_connection(conn)
    return None


def set_period(user_id, day_of_week, period_number, subject):
    """Inserts or updates a single period (day 1-5, period 1-6) for a user."""
    result = execute_query(
        """
        INSERT INTO schedule (user_id, day_of_week, period_number, subject)
        VALUES (?, ?, ?, ?)
        ON CONFLICT (user_id, day_of_week, period_number)
        DO UPDATE SET subject = excluded.subject
        """,
        (user_id, day_of_week, period_number, subject),
    )
    return result is not None


def get_weekly_schedule(user_id):
    """Returns a user's full Mon-Fri schedule sorted by day and period."""
    rows = execute_query(
        """
        SELECT day_of_week, period_number, subject
        FROM schedule
        WHERE user_id = ?
        ORDER BY day_of_week, period_number
        """,
        (user_id,),
    )
    return [dict(row) for row in rows] if rows is not None else []
